-- =====================================================================================================
-- Audit de licence du contenu de jeu de DeepCore : requêtes d'usage (LECTURE SEULE)
-- Ticket Project #7 « DeepCore : audit de licence de tout le contenu de jeu » (25/11/2026).
--
-- * Aucune écriture : SELECT uniquement. À lancer dans une transaction en lecture seule :
--     begin; set transaction read only;   -- puis la requête ;   rollback;
--   (dans l'éditeur SQL de Supabase, lancer chaque requête seule : l'éditeur n'affiche que le dernier résultat.)
-- * Résultats : comptes agrégés seulement. Aucun identifiant, aucun nom de personnage ni de joueur ; les seuls
--   noms renvoyés sont ceux d'éléments du référentiel (sous-classe, don, sort...), déjà lisibles publiquement.
-- * Jointure par NOM FRANÇAIS (translations), jamais par identifiant : les identifiants de la production
--   diffèrent de ceux de la pile locale (ébauches créées par l'import XML hors migration, cf. D58/D59).
-- * Classification reprise du registre `registre-licence-contenu.md` (pile locale, migrations jusqu'à
--   20261124091700). Un élément présent en production mais absent de l'audit ressort en
--   « non audité (absent de la pile locale) » ; une ébauche d'import XML en « ébauche (placeholder import XML) ».
-- * Testées sur la pile locale (0 personnage) : syntaxe validée, Q3 renvoie 0 ligne (tout le référentiel
--   local est couvert par la classification).
-- =====================================================================================================

-- -----------------------------------------------------------------------------------------------------
