-- Noms français du référentiel (translations), par type d'entité.
nom_fr as (
  select entity_type, entity_id, value as nom
  from public.translations
  where field_name = 'name' and locale = 'fr'
),
-- Une ligne par élément du référentiel en base, avec sa clé portable (parent, nom) et sa classification d'audit.
ref as (
  select 'race'::text as categorie, r.id, ''::text as parent, n.nom, r.is_incomplete as ebauche
  from public.races r left join nom_fr n on n.entity_type = 'race' and n.entity_id = r.id::text
  union all
  select 'subrace', s.id, nr.nom, n.nom, false
  from public.subraces s
  left join nom_fr n on n.entity_type = 'subrace' and n.entity_id = s.id::text
  left join nom_fr nr on nr.entity_type = 'race' and nr.entity_id = s.race_id::text
  union all
  select 'lineage', l.id, l.lineage_group, n.nom, false
  from public.race_lineages l left join nom_fr n on n.entity_type = 'race_lineage' and n.entity_id = l.id::text
  union all
  select 'class', c.id, '', n.nom, false
  from public.classes c left join nom_fr n on n.entity_type = 'class' and n.entity_id = c.id::text
  union all
  select 'subclass', s.id, nc.nom, n.nom, false
  from public.subclasses s
  left join nom_fr n on n.entity_type = 'subclass' and n.entity_id = s.id::text
  left join nom_fr nc on nc.entity_type = 'class' and nc.entity_id = s.class_id::text
  union all
  select 'feat', f.id, '', n.nom, false
  from public.feats f left join nom_fr n on n.entity_type = 'feat' and n.entity_id = f.id::text
  union all
  select 'invocation', i.id, '', n.nom, false
  from public.invocations i left join nom_fr n on n.entity_type = 'invocation' and n.entity_id = i.id::text
  union all
  select 'background', b.id, '', n.nom, b.is_incomplete
  from public.backgrounds b left join nom_fr n on n.entity_type = 'background' and n.entity_id = b.id::text
  union all
  select 'spell', s.id, '', n.nom, s.is_incomplete
  from public.spells s left join nom_fr n on n.entity_type = 'spell' and n.entity_id = s.id::text
),
ref_classe as (
  select ref.*, coalesce(a.classification,
           case when ref.ebauche then 'ébauche (placeholder import XML)' else 'non audité (absent de la pile locale)' end
         ) as classification
  from ref
  left join audit a on a.categorie = ref.categorie and a.parent = ref.parent and a.nom = ref.nom
),
perso as (
  select id, (not coalesce(is_archived, false) and not coalesce(is_dead, false)) as actif from public.characters
),
usage as (
  -- race, sous-race, lignée, historique (colonnes de characters)
  select 'race' as categorie, rc.parent, rc.nom, rc.classification, p.id as pid, p.actif, null::text as statut
  from perso p join public.characters c on c.id = p.id join ref_classe rc on rc.categorie = 'race' and rc.id = c.race_id
  union all
  select 'subrace', rc.parent, rc.nom, rc.classification, p.id, p.actif, null
  from perso p join public.characters c on c.id = p.id join ref_classe rc on rc.categorie = 'subrace' and rc.id = c.subrace_id
  union all
  select 'lineage', rc.parent, rc.nom, rc.classification, p.id, p.actif, null
  from perso p join public.characters c on c.id = p.id join ref_classe rc on rc.categorie = 'lineage' and rc.id = c.lineage_id
  union all
  select 'background', rc.parent, rc.nom, rc.classification, p.id, p.actif, null
  from perso p join public.characters c on c.id = p.id join ref_classe rc on rc.categorie = 'background' and rc.id = c.background_id
  union all
  -- classes et sous-classes
  select 'class', rc.parent, rc.nom, rc.classification, p.id, p.actif, null
  from perso p join public.character_classes cc on cc.character_id = p.id join ref_classe rc on rc.categorie = 'class' and rc.id = cc.class_id
  union all
  select 'subclass', rc.parent, rc.nom, rc.classification, p.id, p.actif, null
  from perso p join public.character_classes cc on cc.character_id = p.id join ref_classe rc on rc.categorie = 'subclass' and rc.id = cc.subclass_id
  union all
  -- dons, invocations
  select 'feat', rc.parent, rc.nom, rc.classification, p.id, p.actif, null
  from perso p join public.character_feats cf on cf.character_id = p.id join ref_classe rc on rc.categorie = 'feat' and rc.id = cf.feat_id
  union all
  select 'invocation', rc.parent, rc.nom, rc.classification, p.id, p.actif, null
  from perso p join public.character_invocations ci on ci.character_id = p.id join ref_classe rc on rc.categorie = 'invocation' and rc.id = ci.invocation_id
  union all
  -- sorts (connus, préparés, innés)
  select 'spell', rc.parent, rc.nom, rc.classification, p.id, p.actif, cs.status
  from perso p join public.character_spells cs on cs.character_id = p.id join ref_classe rc on rc.categorie = 'spell' and rc.id = cs.spell_id
  union all
  -- options de classe : chosen_value = nom FR de l'option (ou code du pacte) ; une valeur inconnue n'est jamais
  -- renvoyée telle quelle (texte libre possible), elle est regroupée sous « (valeur non reconnue) ».
  select 'class_option', cf.choice_type,
         case when a.nom is not null then cco.chosen_value else '(valeur non reconnue)' end,
         coalesce(a.classification, 'non audité (absent de la pile locale)'), p.id, p.actif, null
  from perso p
  join public.character_class_options cco on cco.character_id = p.id
  join public.class_features cf on cf.id = cco.class_feature_id
  left join audit a on a.categorie = 'class_option' and a.parent = cf.choice_type and a.nom = cco.chosen_value
  where cf.choice_type in ('manoeuvre', 'metamagie', 'style_combat', 'discipline_elementaire', 'pacte',
                           'infusion', 'tir_arcanique', 'rune')
)
select
  case when grouping(categorie) = 1 then '(total)' else categorie end as categorie,
  case when grouping(nom) = 1 then '(sous-total)'
       else coalesce(nullif(parent, '') || ' : ', '') || coalesce(nom, '(sans nom)') end as element_parent_et_nom,
  case when grouping(classification) = 1 then '(toutes)' else classification end as classification,
  count(distinct pid) as nb_personnages,
  count(distinct pid) filter (where actif) as nb_actifs,
  count(distinct pid) filter (where statut = 'connu') as nb_sort_connu,
  count(distinct pid) filter (where statut = 'préparé') as nb_sort_prepare,
  count(distinct pid) filter (where statut = 'inné') as nb_sort_inne
from usage
group by grouping sets ((categorie, parent, nom, classification), (categorie, classification), ())
order by grouping(categorie), categorie, grouping(nom) desc, classification, nb_personnages desc, element_parent_et_nom;

