    ('class_option', 'style_combat', 'Combat à deux mains', 'SRD, texte non conforme')
),
-- Noms français du référentiel (translations), par type d'entité.
nom_fr as (
  select entity_type, entity_id, value as nom
  from public.translations
  where field_name = 'name' and locale = 'fr'
),
-- Une ligne par élément du référentiel en base, avec sa clé portable (parent, nom) et sa classification d'audit.
ref as (
  select 'race'::text as categorie, r.id, ''::text as parent, n.nom, r.is_incomplete as ebauche
  from public.races r left join nom_fr n on n.entity_type = 'race' and n.entity_id = r.id::text
  union all
  select 'subrace', s.id, nr.nom, n.nom, false
  from public.subraces s
  left join nom_fr n on n.entity_type = 'subrace' and n.entity_id = s.id::text
  left join nom_fr nr on nr.entity_type = 'race' and nr.entity_id = s.race_id::text
  union all
  select 'lineage', l.id, l.lineage_group, n.nom, false
  from public.race_lineages l left join nom_fr n on n.entity_type = 'race_lineage' and n.entity_id = l.id::text
  union all
  select 'class', c.id, '', n.nom, false
  from public.classes c left join nom_fr n on n.entity_type = 'class' and n.entity_id = c.id::text
  union all
  select 'subclass', s.id, nc.nom, n.nom, false
  from public.subclasses s
  left join nom_fr n on n.entity_type = 'subclass' and n.entity_id = s.id::text
  left join nom_fr nc on nc.entity_type = 'class' and nc.entity_id = s.class_id::text
  union all
  select 'feat', f.id, '', n.nom, false
  from public.feats f left join nom_fr n on n.entity_type = 'feat' and n.entity_id = f.id::text
  union all
  select 'invocation', i.id, '', n.nom, false
  from public.invocations i left join nom_fr n on n.entity_type = 'invocation' and n.entity_id = i.id::text
  union all
  select 'background', b.id, '', n.nom, b.is_incomplete
  from public.backgrounds b left join nom_fr n on n.entity_type = 'background' and n.entity_id = b.id::text
  union all
  select 'spell', s.id, '', n.nom, s.is_incomplete
  from public.spells s left join nom_fr n on n.entity_type = 'spell' and n.entity_id = s.id::text
),
ref_classe as (
  select ref.*, coalesce(a.classification,
           case when ref.ebauche then 'ébauche (placeholder import XML)' else 'non audité (absent de la pile locale)' end
         ) as classification
  from ref
  left join audit a on a.categorie = ref.categorie and a.parent = ref.parent and a.nom = ref.nom
),
touche as (
  select c.id,
    bool_or(rc.classification = 'hors SRD') as hors_srd,
    bool_or(rc.classification = 'SRD, texte non conforme') as non_conforme
  from public.characters c
  left join ref_classe rc on
        (rc.categorie = 'race' and rc.id = c.race_id)
     or (rc.categorie = 'subrace' and rc.id = c.subrace_id)
     or (rc.categorie = 'lineage' and rc.id = c.lineage_id)
     or (rc.categorie = 'background' and rc.id = c.background_id)
     or (rc.categorie = 'class' and rc.id in (select class_id from public.character_classes where character_id = c.id))
     or (rc.categorie = 'subclass' and rc.id in (select subclass_id from public.character_classes where character_id = c.id))
     or (rc.categorie = 'feat' and rc.id in (select feat_id from public.character_feats where character_id = c.id))
     or (rc.categorie = 'invocation' and rc.id in (select invocation_id from public.character_invocations where character_id = c.id))
     or (rc.categorie = 'spell' and rc.id in (select spell_id from public.character_spells where character_id = c.id))
  group by c.id
)
select c.edition,
       count(*) as nb_personnages,
       count(*) filter (where not coalesce(c.is_archived, false) and not coalesce(c.is_dead, false)) as nb_actifs,
       count(*) filter (where t.hors_srd) as nb_avec_element_hors_srd,
       count(*) filter (where t.non_conforme) as nb_avec_element_srd_texte_non_conforme,
       count(*) filter (where not coalesce(t.hors_srd, false)) as nb_sans_aucun_element_hors_srd
from public.characters c join touche t on t.id = c.id
group by rollup (c.edition)
order by c.edition nulls last;

-- -----------------------------------------------------------------------------------------------------
-- Q3. Référentiel de la production NON couvert par l'audit (ébauches d'import XML, lignes ajoutées hors
--     migration, renommages). Noms du référentiel seulement (lisibles publiquement), avec le nombre de
--     personnages qui les utilisent. Sur la pile locale : 0 ligne.
-- -----------------------------------------------------------------------------------------------------
