-- Noms français du référentiel (translations), par type d'entité.
nom_fr as (
  select entity_type, entity_id, value as nom
  from public.translations
  where field_name = 'name' and locale = 'fr'
),
-- Une ligne par élément du référentiel en base, avec sa clé portable (parent, nom) et sa classification d'audit.
ref as (
  select 'race'::text as categorie, r.id, ''::text as parent, n.nom, r.is_incomplete as ebauche
  from public.races r left join nom_fr n on n.entity_type = 'race' and n.entity_id = r.id::text
  union all
  select 'subrace', s.id, nr.nom, n.nom, false
  from public.subraces s
  left join nom_fr n on n.entity_type = 'subrace' and n.entity_id = s.id::text
  left join nom_fr nr on nr.entity_type = 'race' and nr.entity_id = s.race_id::text
  union all
  select 'lineage', l.id, l.lineage_group, n.nom, false
  from public.race_lineages l left join nom_fr n on n.entity_type = 'race_lineage' and n.entity_id = l.id::text
  union all
  select 'class', c.id, '', n.nom, false
  from public.classes c left join nom_fr n on n.entity_type = 'class' and n.entity_id = c.id::text
  union all
  select 'subclass', s.id, nc.nom, n.nom, false
  from public.subclasses s
  left join nom_fr n on n.entity_type = 'subclass' and n.entity_id = s.id::text
  left join nom_fr nc on nc.entity_type = 'class' and nc.entity_id = s.class_id::text
  union all
  select 'feat', f.id, '', n.nom, false
  from public.feats f left join nom_fr n on n.entity_type = 'feat' and n.entity_id = f.id::text
  union all
  select 'invocation', i.id, '', n.nom, false
  from public.invocations i left join nom_fr n on n.entity_type = 'invocation' and n.entity_id = i.id::text
  union all
  select 'background', b.id, '', n.nom, b.is_incomplete
  from public.backgrounds b left join nom_fr n on n.entity_type = 'background' and n.entity_id = b.id::text
  union all
  select 'spell', s.id, '', n.nom, s.is_incomplete
  from public.spells s left join nom_fr n on n.entity_type = 'spell' and n.entity_id = s.id::text
),
ref_classe as (
  select ref.*, coalesce(a.classification,
           case when ref.ebauche then 'ébauche (placeholder import XML)' else 'non audité (absent de la pile locale)' end
         ) as classification
  from ref
  left join audit a on a.categorie = ref.categorie and a.parent = ref.parent and a.nom = ref.nom
)
select rc.categorie, coalesce(nullif(rc.parent, '') || ' : ', '') || coalesce(rc.nom, '(sans nom)') as element,
       rc.classification,
       (select count(*) from public.characters c
         where (rc.categorie = 'race' and c.race_id = rc.id) or (rc.categorie = 'background' and c.background_id = rc.id)
            or (rc.categorie = 'subrace' and c.subrace_id = rc.id) or (rc.categorie = 'lineage' and c.lineage_id = rc.id)) as nb_personnages_identite,
       (select count(distinct cs.character_id) from public.character_spells cs where rc.categorie = 'spell' and cs.spell_id = rc.id) as nb_personnages_sort,
       (select count(distinct cc.character_id) from public.character_classes cc
         where (rc.categorie = 'class' and cc.class_id = rc.id) or (rc.categorie = 'subclass' and cc.subclass_id = rc.id)) as nb_personnages_classe,
       (select count(distinct x.character_id) from public.character_feats x where rc.categorie = 'feat' and x.feat_id = rc.id)
     + (select count(distinct x.character_id) from public.character_invocations x where rc.categorie = 'invocation' and x.invocation_id = rc.id) as nb_personnages_don_invocation
from ref_classe rc
where rc.classification not in ('SRD 5.1', 'SRD 5.2', 'hors SRD', 'SRD, texte non conforme')
order by 1, 2;

-- -----------------------------------------------------------------------------------------------------
-- Q4. Colonne `traits_2024` (races/sous-races) : présente en production d'après Nexus (commit dc0ec2b du
--     24/10/2026) mais créée HORS de l'historique de migrations de DeepCore (absente de la pile locale).
--     Inventaire du contenu (noms des traits seulement, longueur du texte) pour l'auditer.
--     `to_jsonb(r) -> 'traits_2024'` fonctionne que la colonne existe ou non (0 ligne sur la pile locale).
-- -----------------------------------------------------------------------------------------------------
with t as (
  select 'race' as categorie, n.value as nom, r.source as source_declaree, to_jsonb(r) -> 'traits_2024' as traits
  from public.races r
  left join public.translations n on n.entity_type = 'race' and n.entity_id = r.id::text and n.field_name = 'name' and n.locale = 'fr'
  union all
  select 'subrace', nr.value || ' : ' || n.value, null, to_jsonb(s) -> 'traits_2024'
  from public.subraces s
  left join public.translations n on n.entity_type = 'subrace' and n.entity_id = s.id::text and n.field_name = 'name' and n.locale = 'fr'
  left join public.translations nr on nr.entity_type = 'race' and nr.entity_id = s.race_id::text and nr.field_name = 'name' and nr.locale = 'fr'
)
select categorie, nom, source_declaree,
       jsonb_array_length(traits) as nb_traits,
       (select string_agg(e ->> 'name', ' | ') from jsonb_array_elements(traits) e) as noms_des_traits,
       (select sum(length(coalesce(e ->> 'description', ''))) from jsonb_array_elements(traits) e) as longueur_texte
from t
where traits is not null and jsonb_typeof(traits) = 'array'
order by 1, 2;

-- Q4 bis. Existence des colonnes et de la migration correspondante (métadonnées seulement).
select table_name, column_name, data_type
from information_schema.columns
where table_schema = 'public' and column_name like '%%2024%%'
order by 1, 2;

